const $=id=>document.getElementById(id),reasonLabels={facts_identifier_missing:'製品・内容の識別情報が不足',date_uncertain:'日付を確認できない',category_uncertain:'カテゴリを確認できない',not_relevant:'対象ニュースとして適さない',duplicate:'既存掲載と重複',useful_product:'有用な製品・イベント情報',minor_update:'軽微なファームウェア更新（ニュース価値が低い）',policy_concern:'掲載方針上の懸念',operator_review:'運用者による確認'};
const errorLabels={category_changed:'記事またはカテゴリが更新されました。編集を開き直してください',category_invalid:'既存カテゴリから選択してください',category_not_editable:'この状態の記事はカテゴリを編集できません',category_transaction_failed:'保存結果が不明です。同じ変更を再送して確認してください',presentation_changed:'記事や表示設定が更新されました。一覧を読み込み直してください',presentation_transaction_failed:'保存結果が不明です。同じ変更を再送して確認してください',presentation_invalid:'表示設定の内容を確認してください',facts_source_gate:'情報源の許可・取得状態を満たしていません。候補は変更していません',facts_recheck_busy:'同じ情報源の確認が進行中です。完了後に開き直してください',facts_source_unavailable:'情報源を取得できませんでした',facts_timeout:'情報源の応答が時間切れになりました',facts_parser_failure:'取得内容を安全に解析できませんでした',facts_listing_structure_changed:'公式一覧の構造が変わっているため更新していません',facts_transaction_failed:'事実の保存結果を確認できません。候補を開き直してください',publication_policy_rejected:'公開方針で掲載対象外と判定されています',facts_incomplete:'掲載に必要なfactsが不足しています',event_date_missing:'開催日が確認できません',duplicate:'既存掲載と重複しています',candidate_changed:'候補が変更されました。詳細を開き直してください',stale_decision:'他の判断・変更が先に確定しました',already_decided:'この候補は判断済みです',idempotency_payload_changed:'前回のrequest IDと内容が異なります',authentication_required:'Accessへログインしてください',authentication_invalid:'Accessの認証期限を確認してください',operator_denied:'このアカウントには管理権限がありません',operator_source_gate:'情報源・公開許可の条件を満たしていません',expired_candidate:'日付または有効期限が掲載条件を満たしていません',sale_validation_failed:'セールの掲載条件を満たしていません',event_validation_failed:'イベントの期限・内容を確認できません',facts_provenance_invalid:'factsの出典を確認できません',label_provenance_invalid:'labelの検証情報が不足しています',source_url_invalid:'原文URLが掲載条件を満たしていません'};
const categoryLabel=key=>({acoustic_guitar:'アコギ',electric_guitar_bass:'ギター・ベース',amps_effects:'アンプ・エフェクター',dtm_software:'DTM・録音・配信',recording_audio:'DTM・録音・配信',creator_streaming:'DTM・録音・配信',recording_streaming:'DTM・録音・配信',artist_guitar:'アーティスト',live_guitar:'イベント',sale:'セール',media_other:'その他'}[key]||'カテゴリ未確定');
// Only the server generates a formal label and determines publication readiness.
const formalTitle=row=>row.morrisReview?.state==='NEEDS_CONFIRMATION'?(row.reviewReference?.verifiedForPublication===false?row.reviewReference.identifier:'Morris公式お知らせ · '+(row.sourceUrl?.split('/').pop()||row.id.slice(0,8))):row.validation?.publishableLabel||(!/要確認|審査待ち|label_required|relevance_uncertain/.test(row.label||'')?row.label:null)||'正式表題を確定できません';
// UI queues explain the next action; publication eligibility remains server-owned.
function reviewQueue(row){
 if(row.preparationState==='READY'||!row.preparationState&&row.validation?.valid===true)return 'approvable';
 if(row.validation?.valid===true||row.preparationState==='EXCLUDED'||row.validation?.errors?.some(e=>['duplicate','candidate_takedown','operator_source_gate','publication_policy_rejected','expired_candidate','source_url_invalid'].includes(e)))return 'editorial';
 if(row.factsReview?.reviewability==='EVIDENCE_WAIT'||row.morrisReview?.confirmationAvailable||row.agmBookReview?.confirmationAvailable||row.canonicalReview||row.assistedEditable)return 'human_facts';
 if(row.preparationState==='RETRY'||row.factsReview?.recoveryClass==='RECOVERABLE_WITH_SOURCE_SPECIFIC_PARSER'||row.validation?.errors?.some(e=>['facts_incomplete','facts_provenance_invalid','label_provenance_invalid'].includes(e)))return 'technical';
 return 'editorial';
}
function statusLabel(row){if(row.factsReview?.reviewability==='EVIDENCE_WAIT')return '出典証拠不足・事実確認待ち';if(row.validation?.valid!==true&&row.factsReview?.recoveryClass==='RECOVERABLE_WITH_SOURCE_SPECIFIC_PARSER')return '技術的な解析更新待ち';if(row.validation?.valid!==true&&reviewQueue(row)==='technical')return '技術的な再確認待ち';if(row.preparationState)return ({READY:'掲載可（掲載判断待ち）',HUMAN_REVIEW:'人間の確認が必要',EXCLUDED:'対象外・自動整理',RETRY:'自動再試行待ち'})[row.preparationState];if(row.factsReview?.reviewability==='EVIDENCE_WAIT')return '証拠待ち（取得制約）';if(row.systemDisposition)return 'システム除外';if(row.morrisReview&&['pending','reopened'].includes(row.status))return row.morrisReview.state==='READY'?'掲載可':row.morrisReview.state==='EXCLUDED'?'除外':'要確認';if(row.status==='approved')return '公開中';if(row.status==='rejected')return '非掲載';if(row.validation?.valid===true)return '掲載可';const state=row.factsReview?.reviewability;if(state==='DUPLICATE_BLOCKED'||row.validation?.errors?.includes('duplicate'))return '重複';if(state==='POLICY_BLOCKED')return '方針確認';if(state==='FACTS_RECOVERY_UNCERTAIN'||row.validation?.errors?.includes('facts_incomplete'))return 'facts不足';return '保留';}
let inspectedArticle=null;
const inspectedId=typeof location==='undefined'?null:new URL(location.href).searchParams.get('candidate');
let items=[],selected=null,session=null,action=null,busy=false,expandedId=null,detailRequest=0,actionRead=0;
const detailCards=new Map();
function closeDetail(){detailRequest++;actionRead++;selected=null;expandedId=null;for(const {detail,button}of detailCards.values()){detail.hidden=true;detail.replaceChildren();button.textContent=button.dataset.closedLabel||'詳細を確認';button.setAttribute('aria-expanded','false');}}
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n;};
const message=text=>{$('notice').textContent=text;};
const displayError=code=>errorLabels[code]||code;
async function api(path,options){const res=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});const data=await res.json();if(!res.ok)throw Object.assign(Error(displayError(data.error)),{code:data.error,status:res.status});return data;}
function originalLink(url){try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)return el('span','原文URLを確認できません');const a=el('a','原記事を開く');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';return a;}catch{return el('span','原文URLを確認できません');}}
function categoryEditor(row,published){
 const section=el('details',undefined,'category-editor'),heading=el('summary','カテゴリを変更'),body=el('div');section.append(heading,body);
 section.addEventListener('toggle',async()=>{
  if(!section.open)return;
  if(busy||presentationBusy||published&&presentationDirty){section.open=false;message('先に進行中の操作、または並び順・ホット表示の変更を保存・取り消ししてください。');return;}
  body.replaceChildren(el('p','カテゴリを読み込んでいます…','meta'));
  try{
   const current=await api('/api/candidates/'+encodeURIComponent(row.id)+'/category');if(!section.open)return;
   body.replaceChildren();if(!current.editable){body.append(el('p','この状態の記事はカテゴリを編集できません。','meta'));return;}
   const label=el('label','表示カテゴリ'),select=el('select');select.setAttribute('aria-label','表示カテゴリ');for(const option of current.options)select.add(new Option(option.label,option.id));select.value=current.category;label.append(select);
   const state=el('p',current.manual?'手動指定中。再解析より優先します。':'自動分類を使用しています。','meta');state.setAttribute('role','status');state.setAttribute('aria-live','polite');
   const review=el('button','変更内容を確認');review.type='button';review.disabled=true;
   const confirm=el('div',undefined,'category-confirm');confirm.hidden=true;const diff=el('p'),save=el('button','カテゴリを保存'),back=el('button','戻る');save.type=back.type='button';confirm.append(diff,save,back);
   const name=k=>current.options.find(o=>o.id===k)?.label||k;let pending=null;
   select.addEventListener('change',()=>{review.disabled=select.value===current.category;confirm.hidden=true;pending=null;});
   review.addEventListener('click',()=>{if(busy||presentationBusy||review.disabled)return;diff.textContent=name(current.category)+' → '+name(select.value);confirm.hidden=false;});
   back.addEventListener('click',()=>{if(!busy)confirm.hidden=true;});
   save.addEventListener('click',async()=>{
    if(busy||presentationBusy||confirm.hidden||select.value===current.category)return;
    if(published&&presentationDirty){state.textContent='並び順・ホット表示の変更を先に保存・取り消ししてください。';return;}
    pending ||= {id:row.id,category:select.value,revision:current.revision,snapshot:current.snapshot,requestId:crypto.randomUUID()};
    busy=true;presentationBusy=true;select.disabled=review.disabled=save.disabled=back.disabled=true;state.textContent='カテゴリを保存中…';
    try{
     session=await api('/api/session');await api('/api/category',{method:'POST',headers:{'Content-Type':'application/json','X-News-CSRF':session.csrf},body:JSON.stringify(pending)});
     state.textContent='カテゴリを保存しました。';message('カテゴリを保存しました。掲載判断・見出し・日付・並び順・ホット表示は変更していません。');
     busy=false;presentationBusy=false;closeDetail();if(published)await loadPresentation();else {presentationDays=[];await refresh();}
    }catch(e){state.textContent=e.message;message(e.message);}
    finally{busy=false;presentationBusy=false;select.disabled=save.disabled=back.disabled=false;review.disabled=select.value===current.category;}
   });
   body.append(label,state,review,confirm,el('p','表示カテゴリの編集です。掲載・非掲載の判断や、原記事から確認したfactsは変更しません。','meta'));
   const history=el('details');history.append(el('summary','カテゴリ編集履歴（'+current.history.length+'件）'));for(const edit of current.history)history.append(el('p',name(edit.old_category)+' → '+name(edit.new_category)+' · '+date(edit.created_at)+' · 管理者 '+edit.actor_id,'meta'));body.append(history);
  }catch(e){body.replaceChildren(el('p',e.message,'blocker'));}
 });return section;
}
const date=value=>value?new Date(value).toLocaleString('ja-JP'):'—';
function sourcePreferenceView(row,card){
 const p=row.sourcePreference;if(!p)return;
 if(p.role==='preferred')card.append(el('p','同じ製品・出来事と日付を正式確認した候補があります。池部楽器を代表記事として優先します。掲載判断は自動実行しません。','meta'));
 if(p.role==='alternative'&&/^[a-zA-Z0-9_-]{1,128}$/.test(p.preferredId||'')){
  const note=el('p',p.reason==='same_verified_co_development_notice'?'同じ共同開発製品の発表を同日付の記事で正式確認したため、池部楽器を優先表示します。発売日は推定していません。 ':'同じ製品・出来事と日付を正式確認した池部楽器の記事を優先します。島村楽器の記事も掲載条件を満たしています。 ','meta'),link=el('a','池部楽器の候補を確認');link.href='?candidate='+encodeURIComponent(p.preferredId);note.append(link);card.append(note);
 }
}
function summary(row,card,compact=false){card.append(el('h3',formalTitle(row)),el('p',`${row.source} · ${date(row.publishedAt)}`,'meta'));const badges=el('div',undefined,'badges');badges.append(el('span','カテゴリ候補','meta'),el('span',categoryLabel(row.category),'category-pill'),el('span',statusLabel(row),row.validation?.valid?'status-pill ready':'status-pill'));card.append(badges,originalLink(row.sourceUrl));sourcePreferenceView(row,card);if(compact){const queue=reviewQueue(row),next={approvable:'原記事と内容を確認して、掲載するか判断してください。',human_facts:'原記事で不足する事実を確認し、確認フォームへ進んでください。',technical:'事実の解析・再確認が必要です。解析失敗だけでは非掲載にしません。',editorial:row.validation?.valid?'事実の検証は完了しています。掲載価値を判断してください。':'重複先・掲載条件を確認して判断してください。'}[queue];card.append(el('p',next,'next-action'));const detail=el('details',undefined,'facts-guidance');detail.append(el('summary','不足項目・確認方法'));card.append(detail);card=detail;}if(row.morrisReview?.state==='NEEDS_CONFIRMATION'){card.append(el('p',row.reviewReference?'審査用識別名（過去の監査記録）。公開用の独自見出しではありません。':'原記事URLによる識別。記事内容は未確認です。','meta'),el('p','正式な独自見出し：未確定','meta'));}if(row.preparationState==='HUMAN_REVIEW'&&row.validation?.valid)card.append(el('p','事実確認は通過しています。掲載する価値・関連性を確認してください。','meta'));if(row.eventType==='firmware'&&['pending','reopened','approved'].includes(row.status))card.append(el('p','通常の更新はニュース価値を慎重に確認します。重要な新機能・不具合修正・安全性・互換性・製品価値の変化が一次情報で確認できる場合は、例外として掲載判断できます。','meta'));if(row.validation?.valid!==true&&row.factsReview){card.append(el('p','掲載には正式factsが必要です。非掲載は、重複・対象外・掲載価値不足などの根拠を別に確認して判断できます。解析失敗だけでは非掲載にしません。','meta'));const r=row.factsReview;if(r.reviewability==='EVIDENCE_WAIT'){card.append(el('p','保存済み一次証拠に必要なfactsが不足しています。自動の詳細再取得は行いません。人間が確認した事実の入力、または根拠のある非掲載判断が必要です。','meta'));return;}if(r.missing?.length)card.append(el('p','不足・未確認：'+r.missing.join(' / '),'meta'));if(r.nextAction)card.append(el('p',r.nextAction,'meta recovery-guidance'));}}
function lifecycleSummary(row,card){const l=row.lifecycle;if(!l)return;if(row.factsReview?.reviewability==='EVIDENCE_WAIT'){card.append(el('p','詳細の自動再取得は停止しています。保存済み一覧証拠に結び付く人間確認、または許可済み日次一覧の新しいfactsで再評価します。','meta'));return;}const text=`最終再確認：${date(l.last_rechecked_at)} · 次回：${date(l.next_recheck_at)} · ${l.recheck_attempt_count||0}回`;card.append(el('p',text,'meta'));card.append(el('p',row.factsReview?.available&&!['DUPLICATE_CONFIRMED','EXPIRED_CONFIRMED','POLICY_BLOCK_CONFIRMED','TAKEDOWN_CONFIRMED'].includes(l.recheck_status)?'許可済みの情報源で再確認可能':'現在は自動取得の対象外です。条件を再確認します。','meta'));if(l.user_publish_interest)card.append(el('p','掲載希望あり · 次回再確認を優先します','meta'));if(l.longPending)card.append(el('span','長期保留','status-pill'));if(['DUPLICATE_CONFIRMED','EXPIRED_CONFIRMED','POLICY_BLOCK_CONFIRMED','TAKEDOWN_CONFIRMED'].includes(l.recheck_status))card.append(el('p','自動掲載不可：'+({DUPLICATE_CONFIRMED:'既存掲載と重複',EXPIRED_CONFIRMED:'期限切れ',POLICY_BLOCK_CONFIRMED:'明示的な掲載方針の対象外',TAKEDOWN_CONFIRMED:'公開停止'}[l.recheck_status])+'（人間の非掲載判断ではありません）','meta'));}
async function interestAction(row){if(busy)return;busy=true;try{session=await api('/api/session');await api('/api/publish-interest',{method:'POST',headers:{'Content-Type':'application/json','X-News-CSRF':session.csrf},body:JSON.stringify({id:row.id,revision:row.revision,snapshot:row.snapshot,interest:!row.lifecycle?.user_publish_interest})});message(row.lifecycle?.user_publish_interest?'掲載希望を取り消しました。':'掲載希望を保存しました。掲載判断ではありません。');}catch(e){message(e.message);}finally{busy=false;await refresh();}}
function decisionControls(row){const controls=el('div',undefined,'actions decision-actions');if(row.factsReview?.reviewability==='EVIDENCE_WAIT')controls.append(el('p','掲載には正式な事実確認が必要です。根拠のある非掲載判断は、facts補完と独立して記録できます。','meta'));for(const [verdict,text]of [['approve','掲載する'],['reject','掲載しない']]){const b=el('button',verdict==='reject'&&row.status==='approved'?'公開を取り下げる':text);b.disabled=busy||!(['pending','reopened'].includes(row.status)||verdict==='reject'&&row.status==='approved')||(verdict==='approve'&&row.validation?.valid!==true);b.addEventListener('click',async()=>{if(busy)return;const request=detailRequest,read=++actionRead;try{const result=await api('/api/candidates/'+encodeURIComponent(row.id));if(request!==detailRequest||read!==actionRead||busy)return;if(!(['pending','reopened'].includes(result.status)||verdict==='reject'&&result.status==='approved')){message('この候補は判断済みです。');await refresh();return;}selected=result;if(verdict==='approve'&&selected.validation?.valid!==true){message('掲載条件が変わりました。更新して確認してください。');await refresh();return;}confirmDecision(verdict);}catch(e){message(e.message);}});controls.append(b);}if(row.factsReview?.reviewability!=='EVIDENCE_WAIT'&&['pending','reopened'].includes(row.status)&&(row.lifecycle?.user_publish_interest||(row.validation?.valid!==true&&!row.validation?.errors?.some(e=>['duplicate','expired_candidate','candidate_takedown','publication_policy_rejected'].includes(e))))){const b=el('button',row.lifecycle?.user_publish_interest?'掲載希望を取り消す':'掲載したい');b.disabled=busy;b.addEventListener('click',()=>interestAction(row));controls.append(b);}return controls;}
function validationView(row,card){card.append(el('p',row.validation.valid?'掲載条件を満たしています':row.validation.errors.map(code=>errorLabels[code]||'確認が必要です').join(' / '),row.validation.valid?'ready':'blocker'));for(const d of row.validation.duplicates){const p=el('p',`重複候補：${d.source_name} / ${d.label} / topic: ${d.topic_key} `,'blocker');p.append(originalLink(d.source_url));card.append(p);}card.append(el('p',`保持期限：${date(row.expiresAt)}${row.saleEndsAt?' / セール終了：'+date(row.saleEndsAt):''}${row.eventEndsAt?' / 開催期限：'+date(row.eventEndsAt):''}`,'meta'));}
function factsView(row,card){const r=row.factsReview;if(!r)return;if(r.reviewability==='EVIDENCE_WAIT')card.append(el('p',r.nextAction,'meta'));card.append(el('h3','事実の確認状況'),el('p',r.missing.length?'不足・未確認：'+r.missing.join(' / '):'掲載に必要な事実は確認済みです。'),el('p',r.available?'再確認可能：許可済みの情報源を使用します。':'この情報源は現在、自動で再確認できません。','meta'),el('p',`最終確認：${date(r.lastVerifiedAt||r.provenance?.verifiedAt)}${r.outcome?' / '+recheckLabel(r.outcome):''}`,'meta'));if(r.surfaceUrl){const p=el('p',r.method==='explicit_product_article_fields'?'原記事に明示された記事対象・用途・機能を確認します。 ':r.method==='existing_listing_parser'?'取得範囲は公式一覧のみです。原記事の本文は取得しません。 ':['targeted_explicit_primary_fields','explicit_ikebe_product_fields'].includes(r.method)?'この候補の一次ページに明示された製品・出来事の情報を確認します。 ':'原記事の明示されたイベント項目を確認します。 ','meta');p.append(originalLink(r.surfaceUrl));card.append(p);}if(r.provenance?.method==='human_official_article_confirmation')card.append(el('p','人が公式記事を確認した記録です。Bot取得の証拠ではありません。外部HTTP取得：0件。','meta'));for(const p of Array.isArray(r.provenance)?r.provenance:[]){if(p.method==='human_canonical_confirmation_v1'){card.append(el('p','認証済み管理者が原記事とcanonicalの誤設定を確認：'+date(p.confirmedAt),'meta'),el('p','元canonical：'+p.originalCanonical,'meta'),el('p','採用URL：'+p.adoptedUrl,'meta'));continue;}card.append(el('p',`${p.factField} · ${p.sourceId} · ${date(p.verifiedAt)} · ${p.extractionMethod} / ${p.parserVersion}`,'meta'));}}
const recheckLabel=code=>({facts_recovered:'確認できた事実を保存しました。掲載条件は別途確認してください。',facts_unchanged:'事実に変更はありません。不足する条件は保留します。',facts_not_recovered:'必要な事実を確認できませんでした。保留を維持します。',facts_not_on_current_surface:'現在の許可済み一覧に該当記事がありません。',facts_date_changed:'公開日が一致しないため更新していません。',facts_identity_changed:'対象の識別情報が一致しないため更新していません。',facts_duplicate_preserved:'既存掲載との重複を維持しています。',facts_already_complete:'事実は確認済みです。',verified_surface:'許可済み情報源を確認済みです。'}[code]||displayError(code));
async function recheckSelected(button){if(busy||!selected)return;busy=true;button.disabled=true;const input={id:selected.id,snapshot:selected.snapshot,revision:selected.revision,requestId:crypto.randomUUID()};message('許可済みの情報源から事実を再確認しています…');try{session=await api('/api/session');const result=await api('/api/facts-recheck',{method:'POST',headers:{'Content-Type':'application/json','X-News-CSRF':session.csrf},body:JSON.stringify(input)});message(recheckLabel(result.outcome)+' 掲載・非掲載の判断は行っていません。');}catch(e){message(e.message+'。候補を開き直して結果を確認してください。');}finally{busy=false;await refresh();await showDetail(input.id);}}
function matchesFilter(row,mode){return ['human_facts','technical','editorial'].includes(mode)?reviewQueue(row)===mode:mode==='retry'?row.preparationState==='RETRY':mode==='excluded'?row.preparationState==='EXCLUDED':mode==='all'||(mode==='approvable'?(row.preparationState?row.preparationState==='READY':row.validation?.valid===true):mode==='review'?(row.preparationState?row.preparationState==='HUMAN_REVIEW':row.validation?.valid!==true):mode==='duplicate'?row.validation?.errors?.includes('duplicate'):row.decision===mode);}
function renderList(){closeDetail();detailCards.clear();const mode=$('mode').value,filtered=items.filter(x=>matchesFilter(x,mode)&&($('source').value==='all'||x.sourceId===$('source').value));$('count').textContent=`${{approvable:'掲載可',human_facts:'事実確認が必要',technical:'技術的な再確認待ち',editorial:'編集・非掲載の判断',review:'要確認',duplicate:'重複',retry:'自動再試行待ち',excluded:'対象外',PUBLISH_REVIEW:'REVIEW'}[mode]||'審査待ち'} ${filtered.length}件（全${items.length}件）`;$('list').replaceChildren();for(const row of (inspectedArticle?[inspectedArticle,...filtered.filter(r=>r.id!==inspectedArticle.id)]:filtered)){const card=el('article',undefined,'card');card.dataset.candidateId=row.id;if(row===inspectedArticle)card.append(el('p','対象記事 · '+statusLabel(row),'meta'));summary(row,card,true);if(row.assistedEditable)card.append(assistedEditButton(row.id));if(row.lifecycle?.longPending)card.append(el('span','長期保留','status-pill'));card.append(decisionControls(row),categoryEditor(row,false));if(row.factsReview?.available&&!row.validation?.valid){const recheck=el('button','事実を再確認');recheck.type='button';recheck.disabled=busy;recheck.addEventListener('click',()=>{selected=row;recheckSelected(recheck);});card.append(recheck);}if(row.lifecycle?.next_recheck_at)card.append(el('p','次回の再確認：'+date(row.lifecycle.next_recheck_at),'meta'));const button=el('button',reviewQueue(row)==='human_facts'?'事実を確認':'詳細を確認'),detail=el('section',undefined,'inline-detail');button.dataset.closedLabel=button.textContent;detail.id='detail-'+row.id;detail.hidden=true;detail.setAttribute('aria-label','候補詳細');button.setAttribute('aria-controls',detail.id);button.setAttribute('aria-expanded','false');button.addEventListener('click',()=>{if(busy)return;if(expandedId===row.id)closeDetail();else showDetail(row.id);});detailCards.set(row.id,{detail,button});card.append(button,detail);$('list').append(card);}if(!filtered.length)$('list').append(el('p','該当する保留候補はありません。'));}
const similarityLabels={EXACT_PATTERN:'同じ判断パターン',STRONG_SIMILAR:'強い共通点',WEAK_SIMILAR:'一部の共通点',INSUFFICIENT:'共通点が不足'};
const signalLabels={source:'同じ情報源',surface:'同じ掲載面',type:'同じ記事・出来事の種類',category:'同じ表示カテゴリ',factStructure:'同じ確認済みfacts構造',reviewReason:'同じ確認理由・未確認条件',freshness:'同じ鮮度区分'};
function insightsView(result,section){
 section.replaceChildren(el('h3','過去の似た判断'));
 if(!result||!Number.isSafeInteger(result.matchedDecisionCount)){section.append(el('p','判断データを確認できません。ご自身で原文と掲載条件をご確認ください。','meta'));return;}
 section.append(el('p',`過去${result.matchedDecisionCount}件 · 掲載 ${result.approveCount} · 非掲載 ${result.rejectCount}`,'meta'));
 const text=result.recommendation==='RECOMMEND_APPROVE'?'掲載寄り':result.recommendation==='RECOMMEND_REJECT'?'非掲載寄り':result.reasonSummary==='contradictory_history'?'判断が分かれているため推薦なし':result.reasonSummary==='publication_blocked'?'現在の掲載条件を満たさないため推薦なし':'まだ判断データが足りません';
 section.append(el('p',text),el('p',`強い根拠 ${result.evidenceCount}件 / 必要 ${result.minimumEvidence}件 · ${similarityLabels[result.similarityLevel]||result.similarityLevel}`,'meta'),el('p','参考情報です。掲載・非掲載は自動で実行されません。','meta'));
 for(const m of result.matches){section.append(el('p',`${m.verdict==='approve'?'掲載':'非掲載'} · ${m.source} / ${categoryLabel(m.category)} / ${m.type} · ${date(m.decidedAt)} · ${reasonLabels[m.reason]||m.reason}`,'meta'),el('p',`共通点：${Object.keys(signalLabels).filter(k=>m.signals[k]).map(k=>signalLabels[k]).join('、')||'不足'} · 方針：${m.policyCompatibility==='SAME'?'同一':m.policyCompatibility==='COMPATIBLE'?'互換':'旧方針（推薦根拠から除外）'} / ${m.policyVersion}`,'meta'));}
 if(result.truncated)section.append(el('p','共通点の一覧は最新50件を表示しています。','meta'));
}
async function loadInsights(row,section,request){
 try{const result=await api('/api/candidates/'+encodeURIComponent(row.id)+'/similar-decisions?revision='+encodeURIComponent(row.revision)+'&snapshot='+encodeURIComponent(row.snapshot));if(request!==detailRequest||expandedId!==row.id)return;insightsView(result,section);
  if(!session?.csrf)return;
  await api('/api/shadow-evaluate',{method:'POST',headers:{'Content-Type':'application/json','X-News-CSRF':session.csrf},body:JSON.stringify({id:row.id,revision:row.revision,snapshot:row.snapshot})});if(request===detailRequest&&expandedId===row.id)await refreshShadow();
 }catch(e){if(request!==detailRequest||expandedId!==row.id)return;section.replaceChildren(el('h3','過去の似た判断'),el('p',e.message,'meta'));}
}

