 if(!data.lowSample){const percent=n=>n===null?'—':(n*100).toFixed(1)+'%';section.append(el('p',`推薦coverage ${percent(data.recommendationCoverage)} · 推薦の一致率 ${percent(data.agreementRate)} · 矛盾率 ${percent(data.contradictionRate)}`,'meta'));}
