 for(const row of excluded.items){const card=el('article',undefined,'card');card.append(el('p',row.label),el('p','自動整理：'+row.review_reason),originalLink(row.source_url));const restore=el('button','再審査へ戻す');restore.addEventListener('click',async()=>{restore.disabled=true;try{const detail=await api('/api/candidates/'+row.id),auth=await api('/api/session');await api('/api/system-restore',{method:'POST',headers:{'Content-Type':'application/json','X-News-CSRF':auth.csrf},body:JSON.stringify({id:row.id,snapshot:detail.snapshot,requestId:crypto.randomUUID()})});message('再審査へ戻しました。公開はしていません。');await refresh();}catch(e){message(e.message);}finally{restore.disabled=false;}});card.append(restore);area.append(card);}
 for(const row of missing.items){const card=el('article',undefined,'card');card.append(el('p',row.source_id+'：候補化前の確認が必要'),el('p',row.reason_code),originalLink(row.normalized_url));area.append(card);}
