function agmBookConfirmation(row,panel){
 if(!row.agmBookReview?.confirmationAvailable)return;
 const section=el('details',undefined,'agm-book-confirmation');section.append(el('summary','書籍発売を原記事で確認して事実を入力'));
 section.append(el('p','書籍発売の記事であることを確認した場合だけ入力してください。これは人間の一次確認であり、自動抽出ではありません。公開日時は保存値を維持します。出版社は原記事に明示がある場合だけ入力し、推測しないでください。保存は公開・掲載判断を行いません。','meta'));
 const form=el('div'),fields={},checks={};
 for(const [key,label,type]of [['bookTitle','正式な書名（原見出し全体は入力しない）','text'],['author','著者','text'],['releaseDate','書籍の発売日（記事の公開日ではない）','date'],['publisher','出版社（明示がある場合のみ・任意）','text']]){const l=el('label',label),i=el('input');i.type=type;i.required=key!=='publisher';if(type==='text')i.maxLength=80;i.setAttribute('aria-label',label);fields[key]=i;l.append(i);form.append(l);}
 const box=el('fieldset');for(const [key,label]of [['primaryArticleChecked','リンク先の原記事を自分で確認した'],['bookIdentityChecked','その原記事に書名・著者・書籍発売が明示されている'],['publicationAndReleaseDatesChecked','記事の公開日と書籍の発売日を区別した'],['acousticRelevanceChecked','アコースティックギターとの関連を確認した'],['noOriginalTextCopied','原見出し・本文の転載や推測補完をしていない']]){const l=el('label'),i=el('input');i.type='checkbox';checks[key]=i;l.append(i,document.createTextNode(label));box.append(l);}
 const save=el('button','確認した書籍の事実を保存・掲載条件を検証');save.type='button';save.disabled=true;const update=()=>{save.disabled=busy||Object.values(fields).some(i=>!i.checkValidity())||Object.values(checks).some(i=>!i.checked);};form.addEventListener('input',update);form.addEventListener('change',update);box.addEventListener('change',update);
 save.addEventListener('click',async()=>{if(save.disabled||busy)return;busy=true;update();try{session=await api('/api/session');const facts=Object.fromEntries(Object.entries(fields).filter(([k,i])=>k!=='publisher'||i.value.trim()).map(([k,i])=>[k,i.value.trim()]));const result=await api('/api/agm-book-facts-confirm',{method:'POST',headers:{'Content-Type':'application/json','X-News-CSRF':session.csrf},body:JSON.stringify({id:row.id,revision:row.revision,snapshot:row.snapshot,requestId:crypto.randomUUID(),facts,checks:Object.fromEntries(Object.entries(checks).map(([k,i])=>[k,i.checked]))})});message(result.validation?.valid?'書籍の人間確認を保存しました。正式検証PASS・掲載判断待ちです。公開していません。':'保存結果を開き直して確認してください。公開していません。');busy=false;await refresh();await showDetail(row.id);}catch(e){message(e.message+'。保存結果を確認してください。公開していません。');}finally{busy=false;update();}});
 section.append(form,box,save);panel.append(section);
}
